
class MultipleMatches(LookupError):
    def __init__(self, values_quantity, xpath):
        self.val_quantity = values_quantity
        self.xpath = xpath

    def __str__(self):
        return (f"Too many elements matched found - {self.val_quantity}. "
                f"Request should be unambiguous. "
                f"Used XPath: {self.xpath}")


class ModificationStringException(Exception):
    pass


class AddItemParameterException(Exception):
    pass


class MatchNotFound(Exception):
    pass
